async function loadTaskImages(task){try{const out=await api('/api/images?task_id='+encodeURIComponent(task.id));const prompt=document.querySelector('#image-prompt');if(prompt&&!prompt.value)prompt.value=out.default_prompt;renderTaskImages(out.images||[])}catch(e){const error=document.querySelector('#visual-error');if(error){error.textContent=e.message;error.hidden=false}}}
function renderTaskImages(images){const preview=document.querySelector('#visual-preview'),history=document.querySelector('#visual-history');if(!preview)return;if(images.length){const latest=images[0];preview.innerHTML=`<img src="${esc(latest.media_url)}" alt="AI-generated visual for ${esc(state.activeTask?.title||'this task')}"><div class="visual-meta"><span>${esc(latest.size)} / ${date(latest.created_at)}</span><a class="text-button" href="${esc(latest.media_url)}" download="rekarasa-visual.png">Download</a></div>`;history.innerHTML=images.length>1?`<div class="eyebrow">PREVIOUS VISUALS</div>${images.slice(1).map(item=>`<a class="visual-thumb" href="${esc(item.media_url)}" target="_blank" rel="noopener"><img src="${esc(item.media_url)}" alt="Saved previous generated visual"><span>${date(item.created_at)}</span></a>`).join('')}`:''}else{preview.innerHTML='<div class="visual-empty"><span>*</span><strong>Your visual will appear here.</strong><small>Saved images remain with this content task.</small></div>';history.innerHTML=''}}
async function generateVisual(task,button){const prompt=document.querySelector('#image-prompt').value.trim(),ratio=document.querySelector('#image-ratio').value,error=document.querySelector('#visual-error');error.hidden=true;setBusy(button,true,'Creating visual...');document.querySelector('#visual-preview').classList.add('is-loading');try{await api('/api/generate-image',{method:'POST',body:JSON.stringify({task_id:task.id,prompt,ratio})});const out=await api('/api/images?task_id='+encodeURIComponent(task.id));renderTaskImages(out.images||[]);toast('Visual generated and saved to this task.')}catch(e){error.textContent=e.message;error.hidden=false;toast(e.message,true)}finally{document.querySelector('#visual-preview')?.classList.remove('is-loading');setBusy(button,false)}}
function formatScript(text){return esc(text).replace(/(^|\n)(HOOK|SCENE|BEAT|ON SCREEN|VOICEOVER|VO|CTA|CLOSE):/gi,'$1<strong class="script-label">$2</strong>').replace(/\n/g,'<br>')}
function formatListing(text){return esc(text).replace(/(^|\n)(PRODUCT TITLE|TITLE|DESCRIPTION|KEY FEATURES|DETAILS):/gi,'$1<strong class="script-label">$2</strong>').replace(/\n/g,'<br>')}
async function generateSingle(task,button){setBusy(button,true,'Generating…');try{await api('/api/generate',{method:'POST',body:JSON.stringify({task_id:task.id})});toast('Draft and review saved.');await workbenchPage(task.id)}catch(e){toast(e.message,true);setBusy(button,false)}}
async function remediate(task,button){setBusy(button,true,'Revising…');try{const out=await api('/api/revise',{method:'POST',body:JSON.stringify({task_id:task.id})});toast(`Remediation ${out.attempt} of ${out.max_attempts} saved.`);await workbenchPage(task.id)}catch(e){toast(e.message,true);setBusy(button,false)}}
