async function openConversation(id){try{const data=await api('/api/conversation?id='+encodeURIComponent(id));const c=data.conversation;const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML='<section class="modal-card conversation-modal"><button class="modal-close" aria-label="Close">×</button><div class="eyebrow">RIWAYAT · CONVERSATION</div><h2 class="conversation-title"></h2><p class="conversation-project"></p><div class="conversation-brief"></div><div class="conversation-plan"></div><div class="conversation-tasks"></div><div class="modal-actions"><button class="button secondary close-conversation">Done</button><button class="button primary continue-conversation">Continue brief →</button></div></section>';document.body.append(overlay);overlay.querySelector('.conversation-title').textContent=c.title;overlay.querySelector('.conversation-project').textContent=(c.project_name||'Project')+' · '+date(c.created_at);overlay.querySelector('.conversation-brief').textContent=c.brief||'No brief saved.';if(data.plan){overlay.querySelector('.conversation-plan').textContent='Planner · '+data.plan.status+' · '+(data.plan.body.objective||'Plan saved')}for(const task of data.tasks){const button=document.createElement('button');button.className='history-task';button.textContent=task.format+' · '+labelStatus(task.status);button.onclick=()=>{overlay.remove();openTask(task.id)};overlay.querySelector('.conversation-tasks').append(button)}overlay.querySelectorAll('.modal-close,.close-conversation').forEach(b=>b.onclick=()=>overlay.remove());overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};overlay.querySelector('.continue-conversation').onclick=()=>{state.continueConversation=c;overlay.remove();navigate('new')}}catch(e){toast(e.message,true)}}
async function historyPage(){const out=await api('/api/history');const items=out.conversations||[];const content=`${pageHead('RIWAYAT','Your conversations.','Return to a brief, plan and the work it started.') }<div class="history-list">${items.length?items.map(c=>`<button class="history-item" data-conversation="${esc(c.id)}"><span class="task-symbol sage">↺</span><span><strong>${esc(c.title||'Creative brief')}</strong><small>${esc(c.project_name||'Project')} · ${date(c.created_at)}${c.brief?' · '+esc(c.brief):''}</small></span><span class="row-arrow">↗</span></button>`).join(''):`<div class="empty-state"><span class="empty-symbol">↺</span><h3>No conversations yet.</h3><p>Start a brief to keep its plan and decisions together.</p><button class="button primary" data-page="new">＋ Start a brief</button></div>`}</div>`;shell(content,'Riwayat')}const baseHistoryPage=historyPage;
