async function settingsPage(){const content=`${pageHead('SETTINGS','Your studio, your settings.','Account, provider connection, usage and review rules.') }<div class="settings-content"><section class="settings-row"><div><div class="eyebrow">SIGNED IN AS</div><h3>${esc(state.user.email)}</h3><p>Private account in this application database.</p></div><button class="button secondary" id="sign-out">Sign out</button></section><section class="settings-row"><div><div class="eyebrow">LANGUAGE MODEL</div><h3>${state.provider?'Groq · '+esc(state.model||'openai/gpt-oss-20b'):providerLabel()}</h3><p>${state.provider?'The API key stays on the server. Token counts are saved when the provider returns them.':'Set GROQ_API_KEY in the server environment to enable live Planner, Writer and Reviewer calls.'}</p></div><span class="status-chip ${state.provider?'pass':'needs'}">${state.provider?'Connected':'Unavailable'}</span></section><section class="settings-row"><div><div class="eyebrow">DATA STORE</div><h3>Persistent SQLite database</h3><p>Project data is isolated by account ownership.</p></div><span class="status-chip pass">Ready</span></section><section class="settings-row rules-settings"><div><div class="eyebrow">REVIEW POLICY</div><h3>Inspectable rules, version 1.0</h3><p>This project's review policy, versioned and inspectable. Not legal advice, not a complete compliance review.</p></div><button class="text-button" id="settings-rules">Inspect rules →</button></section><section class="settings-row"><div><div class="eyebrow">DATA & PRIVACY</div><h3>What leaves this app</h3><p>Your account stays local. Brief and draft text is sent to the text model. See exactly which fields, and which never leave.</p></div><button class="text-button" id="settings-privacy">See disclosure →</button></section><div class="settings-foot">Publishing is not connected. Export is manual and never marks content as published.</div></div>`;shell(content,'Settings');document.querySelector('#sign-out').onclick=async()=>{try{await api('/api/logout',{method:'POST',body:'{}'})}finally{state.user=null;state.csrf=null;authPage()}};document.querySelector('#settings-rules').onclick=showRules;document.querySelector('#settings-privacy').onclick=showPrivacy}const baseSettingsPage=settingsPage;
