const baseWorkbenchPage=workbenchPage;
function sentences(text){return String(text||'').replace(/([.!?])\s+/g,'$1\n').split('\n').map(line=>line.trim()).filter(Boolean)}
function sentenceDiff(before,after){
 const a=sentences(before),b=sentences(after),n=a.length,m=b.length;
 const table=Array.from({length:n+1},()=>new Uint16Array(m+1));
 for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)table[i][j]=a[i]===b[j]?table[i+1][j+1]+1:Math.max(table[i+1][j],table[i][j+1]);
 const out=[];let i=0,j=0;
 while(i<n&&j<m){if(a[i]===b[j]){out.push({type:'same',text:a[i]});i++;j++}else if(table[i+1][j]>=table[i][j+1]){out.push({type:'del',text:a[i]});i++}else{out.push({type:'add',text:b[j]});j++}}
 while(i<n)out.push({type:'del',text:a[i++]});
 while(j<m)out.push({type:'add',text:b[j++]});
 return out;
}
function versionDiffPanel(task){
 const versions=task.versions||[];
 if(versions.length<2)return;
 const list=document.querySelector('.version-list');
 const section=document.querySelector('.version-section');
 if(!list||!section)return;
 const previous=versions.at(-2),latest=versions.at(-1);
 const changed=sentenceDiff(previous.content,latest.content).filter(part=>part.type!=='same').length;
 const box=document.createElement('details');
 box.className='version-diff';
 box.open=changed>0;
 const summary=document.createElement('summary');
 summary.textContent=changed?`What changed · v${previous.version} → v${latest.version} · ${changed} line${changed===1?'':'s'}`:`What changed · v${previous.version} → v${latest.version} · identical wording`;
 const body=document.createElement('div');
 body.className='diff-body';
 for(const part of sentenceDiff(previous.content,latest.content)){
  if(part.type==='same'&&body.childElementCount>6)continue;
  const line=document.createElement('p');
  line.className='diff-line '+part.type;
  line.textContent=(part.type==='add'?'+ ':part.type==='del'?'\u2212 ':'\u00a0\u00a0')+part.text;
  body.append(line);
 }
 box.append(summary,body);
 list.before(box);
}
workbenchPage=async function(id){await baseWorkbenchPage(id);const task=state.activeTask;if(!task)return;versionDiffPanel(task);const trail=document.querySelector('.agent-trail');if(trail&&task.agent_runs?.length){trail.innerHTML='<div class="eyebrow">AGENT EXCHANGES · FULL HISTORY</div>';for(const run of task.agent_runs){const item=document.createElement('details');item.className='agent-run';const summary=document.createElement('summary');summary.textContent=run.role+' · '+run.status+' · '+date(run.created_at);const preview=document.createElement('p');preview.textContent=(run.summary||run.error_code||'Agent run recorded').slice(0,420);item.append(summary,preview);trail.append(item)}}const display=document.querySelector('#draft-display');const version=task.versions?.at(-1);if(display&&version){const names=JSON.parse(version.source_ids||'[]').map(source=>state.projects.find(p=>p.id===task.project_id)?.sources.find(s=>s.id===source)?.name).filter(Boolean);const refs=document.createElement('div');refs.className='source-references';refs.textContent=names.length?'Sources · '+names.join(', '):'No source references attached to this draft';display.after(refs)}};
start();
